function ejecutarConPrioridad(tareas) {
  return new Promise(resolve => {
    const altas = tareas.filter(t => t.prioridad === 'alta');
    const normales = tareas.filter(t => t.prioridad === 'normal');

    // Encola las altas como microtasks
    for (const tarea of altas) {
      queueMicrotask(tarea.fn);
    }

    // Encola las normales como macrotasks y resuelve cuando la última corra
    let completadas = 0;
    if (normales.length === 0) {
      // Si no hay normales, resuelve como microtask
      queueMicrotask(resolve);
      return;
    }

    for (const tarea of normales) {
      setTimeout(() => {
        tarea.fn();
        completadas++;
        if (completadas === normales.length) resolve();
      }, 0);
    }
  });
}

const log = [];
await ejecutarConPrioridad([
  { fn: () => log.push('normal-1'), prioridad: 'normal' },
  { fn: () => log.push('alta-1'),   prioridad: 'alta' },
  { fn: () => log.push('normal-2'), prioridad: 'normal' },
  { fn: () => log.push('alta-2'),   prioridad: 'alta' },
]);

console.log(log);
